INSERT INTO servicios(nombre,descripcion,imagen_url,categoria_id) SELECT 'Masaje facial', 'Técnica revitalizante que mejora la circulación sanguínea en el rostro, relaja los músculos faciales y devuelve la luminosidad natural a tu piel.', 'https://images.unsplash.com/photo-1512290923902-8a9f81dc236c?w=900&q=80', id FROM categorias WHERE nombre='Masajes' AND NOT EXISTS (SELECT 1 FROM servicios WHERE nombre='Masaje facial');
INSERT INTO servicios(nombre,descripcion,imagen_url,categoria_id) SELECT 'Masaje relajante', 'Movimientos suaves y armónicos diseñados para calmar el sistema nervioso, reducir los niveles de estrés y disolver la tensión acumulada.', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=900&q=80', id FROM categorias WHERE nombre='Masajes' AND NOT EXISTS (SELECT 1 FROM servicios WHERE nombre='Masaje relajante');
INSERT INTO servicios(nombre,descripcion,imagen_url,categoria_id) SELECT 'Masaje mixto', 'Combinación perfecta entre técnicas relajantes y descontracturantes para atender zonas de tensión profunda sin perder la paz interior.', 'https://images.unsplash.com/photo-1519823551278-64ac92734fb1?w=900&q=80', id FROM categorias WHERE nombre='Masajes' AND NOT EXISTS (SELECT 1 FROM servicios WHERE nombre='Masaje mixto');
INSERT INTO servicios(nombre,descripcion,imagen_url,categoria_id) SELECT 'Masajes descontracturantes', 'Enfocado en liberar los nudos musculares y contracturas severas causadas por malas posturas, estrés o esfuerzo físico excesivo.', 'https://images.unsplash.com/photo-1544161515-4ab6ce6db874?w=900&q=80', id FROM categorias WHERE nombre='Masajes' AND NOT EXISTS (SELECT 1 FROM servicios WHERE nombre='Masajes descontracturantes');
INSERT INTO servicios(nombre,descripcion,imagen_url,categoria_id) SELECT 'Reflexologia podal', 'Estimulación de puntos reflejos en los pies que corresponden a distintos órganos y sistemas del cuerpo, promoviendo el equilibrio orgánico.', 'https://images.unsplash.com/photo-1512290923902-8a9f81dc236c?w=900&q=80', id FROM categorias WHERE nombre='Reflexología' AND NOT EXISTS (SELECT 1 FROM servicios WHERE nombre='Reflexologia podal');
INSERT INTO servicios(nombre,descripcion,imagen_url,categoria_id) SELECT 'Bambúterapia', 'Terapia con cañas de bambú que se adaptan a la anatomía corporal, ideal para drenar, reducir, moldear y relajar profundamente.', 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?w=900&q=80', id FROM categorias WHERE nombre='Masajes' AND NOT EXISTS (SELECT 1 FROM servicios WHERE nombre='Bambúterapia');
INSERT INTO servicios(nombre,descripcion,imagen_url,categoria_id) SELECT 'Dulce espera (embarazada)', 'Masaje prenatal especializado y seguro que alivia dolores lumbares, pesadez en piernas y relaja a la futura mamá con total delicadeza.', 'https://images.unsplash.com/photo-1519823551278-64ac92734fb1?w=900&q=80', id FROM categorias WHERE nombre='Masajes' AND NOT EXISTS (SELECT 1 FROM servicios WHERE nombre='Dulce espera (embarazada)');
INSERT INTO servicios(nombre,descripcion,imagen_url,categoria_id) SELECT 'Masaje sueco', 'Técnica clásica occidental con caricias deslizantes, amasamiento y fricción para relajar los músculos y estimular la circulación general.', 'https://images.unsplash.com/photo-1544161515-4ab6ce6db874?w=900&q=80', id FROM categorias WHERE nombre='Masajes' AND NOT EXISTS (SELECT 1 FROM servicios WHERE nombre='Masaje sueco');
INSERT INTO servicios(nombre,descripcion,imagen_url,categoria_id) SELECT 'Reductor', 'Masaje con maniobras vigorosas destinado a movilizar grasa localizada, mejorar el contorno corporal y activar el metabolismo local.', 'https://images.unsplash.com/photo-1512290923902-8a9f81dc236c?w=900&q=80', id FROM categorias WHERE nombre='Masajes' AND NOT EXISTS (SELECT 1 FROM servicios WHERE nombre='Reductor');
