INSERT INTO servicios(nombre,descripcion,imagen_url,categoria_id) SELECT 'Descarga muscular', 'Diseñado para deportistas y personas con alta carga física; elimina el ácido láctico acumulado y previene lesiones musculares.', 'https://images.unsplash.com/photo-1519823551278-64ac92734fb1?w=900&q=80', id FROM categorias WHERE nombre='Terapia física' AND NOT EXISTS (SELECT 1 FROM servicios WHERE nombre='Descarga muscular');
